<script setup>
import {onMounted,ref,computed} from 'vue'; import {api,API_BASE} from '../api';
const listings=ref([]),selected=ref(null),bid=ref({companyName:'',contactName:'',email:'',amount:0,notes:''}),msg=ref('');
async function load(){listings.value=(await api.get('/marketplace/listings')).data} function open(x){selected.value=x;bid.value.amount=x.minimumBid;msg.value=''} async function submit(){try{await api.post(`/marketplace/listings/${selected.value.id}/bids`,bid.value);msg.value='Bid submitted successfully. The owner will review bids after the bidding period.';await load()}catch(e){msg.value=e.response?.data?.error||'Unable to submit bid.'}}
const mediaUrl=u=>u?.startsWith('/uploads')?API_BASE.replace('/api','')+u:u; onMounted(load);
</script>
<template><div class="market-public"><div class="hero"><div><h1>Available warehouse spaces</h1><p>Explore owner-approved warehouse spaces, view photos and floor plans, and submit a bid during the published bidding period.</p></div><a class="btn secondary" href="/login">Tenant login</a></div><div class="grid3 section"><article v-for="x in listings" :key="x.id" class="card listing-card"><div class="listing-media"><img v-if="x.media?.[0]" :src="mediaUrl(x.media[0].url)" :alt="x.media[0].caption||x.title"><div v-else class="media-empty">Floor plan / photos coming soon</div><span class="pill" :class="x.phase==='OPEN'?'good':'warn'">{{x.phase}}</span></div><div class="listing-body"><small>{{x.siteName}} · {{x.warehouseName}}</small><h3>{{x.title}}</h3><p>{{x.description}}</p><div class="listing-stats"><div><span>Available</span><b>{{Number(x.availableSqft).toLocaleString()}} sqft</b></div><div><span>Minimum bid</span><b>{{x.currency}} {{Number(x.minimumBid).toLocaleString()}}</b></div><div><span>Bidding ends</span><b>{{new Date(x.bidEnd).toLocaleDateString()}}</b></div></div><button class="btn" :disabled="x.phase!=='OPEN'" @click="open(x)">{{x.phase==='OPEN'?'View & submit bid':'Bidding not open'}}</button></div></article></div>
<div v-if="selected" class="modal-overlay"><div class="card modal-dialog"><div class="section-head"><div><h3>{{selected.title}}</h3><span>Minimum bid {{selected.currency}} {{Number(selected.minimumBid).toLocaleString()}}</span></div><button class="mini-btn" @click="selected=null">Close</button></div><div v-if="selected.media?.length" class="media-gallery"><figure v-for="m in selected.media" :key="m.id||m.url"><img :src="mediaUrl(m.url)"><figcaption>{{m.type.replace('_',' ')}} · {{m.caption}}</figcaption></figure></div><div class="callout">Bidding period: {{new Date(selected.bidStart).toLocaleString()}} → {{new Date(selected.bidEnd).toLocaleString()}}. Bids below the minimum amount are rejected automatically.</div><div class="form-grid section"><div class="field"><label>Company</label><input v-model="bid.companyName"></div><div class="field"><label>Contact person</label><input v-model="bid.contactName"></div><div class="field"><label>Email</label><input v-model="bid.email"></div><div class="field"><label>Your bid ({{selected.currency}})</label><input type="number" :min="selected.minimumBid" v-model.number="bid.amount"></div></div><div class="field"><label>Proposal / requirements</label><textarea v-model="bid.notes" placeholder="Lease term, intended use, special requirements..."></textarea></div><button class="btn section" @click="submit">Submit bid</button><div v-if="msg" class="callout section">{{msg}}</div></div></div></div></template>